                | "/="
                | "%="
                | "**="
                | "&&="
                | "||="
                | "??="
                | "&="
                | "|="
                | "^="
                | "<<="
                | ">>="
                | ">>>="
                | "++"
                | "--"
                | "=>"
                | "function"
                | "class"
                | "delete"
                | "yield"
                | "await"
