            .and_then(|tree| tree["span"]["start"].as_u64())
            .map_or(from, |start| usize::try_from(start).expect("host span"));
        if source[from..to].contains(['\r', '\n', '\u{2028}', '\u{2029}']) {
            return Err("ReturnLineTerminator");
        }
        expression(terms, parameters)
