    match checked {
        Ok(value) => {
            contract["result"] = value;
            contract["callEffects"] = json!("none");
            contract["status"] = json!("supported");
        }
        Err(reason) => {
            contract["gap"] =
                json!({"reason":reason,"span":body.first().map(|tree| &tree["span"])});
        }
    }
