        Ok(trees) => trees,
        Err(error) => {
            return json!({"path":path,"contentId":content_identifier,"bytes":source.len(),"declarations":[],"exports":[],"imports":[],
            "gaps":[{"reason":"LexicalFailure","start":error.span.start}],"moduleEffects":"unknown"});
