            .get(cursor)
            .is_some_and(|tree| text(tree) == "default");
        if default_export {
            cursor += 1;
        }
        let asynchronous = trees.get(cursor).is_some_and(|tree| text(tree) == "async");
        if asynchronous {
            cursor += 1;
