            .get(cursor)
            .is_some_and(|tree| text(tree) == "function")
            && trees.get(cursor + 1).is_some_and(identifier)
            && trees
                .get(cursor + 2)
                .is_some_and(|tree| group(tree, "paren"))
            && trees
                .get(cursor + 3)
                .is_some_and(|tree| group(tree, "brace"))
