                exports.extend(named);
            } else {
                gaps.push(json!({"reason":"UnsupportedExport","start":span_start(&trees[start])}));
            }
            at = cursor + 1;
            if trees.get(at).is_some_and(|tree| text(tree) == ";") {
                at += 1;
            }
            continue;
        }
        if text(&trees[start]) == "import" {
            let mut end = start + 1;
